"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["3868"],{3603(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>m,frontMatter:()=>s,contentTitle:()=>a,toc:()=>d,assets:()=>c});var o=JSON.parse('{"id":"reference/monitor/howtos/understandSyncStatus","title":"How to understand synchronization status?","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/understandSyncStatus.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/understandSyncStatus","permalink":"/personal-av-docs/docs/reference/monitor/howtos/understandSyncStatus","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/understandSyncStatus.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to understand synchronization status?","sidebar_label":"How to understand synchronization status","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/monitor/howtos/understandSyncStatus","format":"md"}}'),r=n(4848),i=n(8453);let s={title:"How to understand synchronization status?",sidebar_label:"How to understand synchronization status",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/monitor/howtos/understandSyncStatus",format:"md"},a,c={},d=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[":::note Edition\n",(0,r.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/monitor/howtos/understandSyncStatus",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsx)(t.p,{children:"How to understand synchronization status?\nSynchronization Status is provided in ALMS to provide a visual clue as to the state of your System, and if the components of the System are in a good state.\nDefinition of a system\nA System in ALMS consists of one of the following configurations:\na router with a third-party SIM\na router and a subscription for a Sierra Wireless Connectivity SIM\na router without a SIM\nSIM subscription only\u2014this type of system does not show a Synchronization Status\nOn ALMS, Synchronization Status is always in reference to the System as a whole. For AirLink router and gateway customers using third-party (non-Sierra Wireless) SIMs, many of the messages that you receive may not be directly relevant.\nSynchronization Status\nSynchronization Status color indicators are Green, Yellow and Red.\nGreen indicates that the System is correctly synchronized. There are no issues with the System and all elements are correctly configured.\nYellow indicates that at least one Warning message has been received in ALMS and will be noted in the Synchronization Log. For most AirLink router and gateway customers we recommend that you review systems in this state, but these issues may not affect the operation of your router or gateway.\nRed indicates that at least one Error message has been received in ALMS and will be noted in the Synchronization Log.  We recommend that you review all Error messages, but some Error messages may not negatively affect the operation of your AirLink router or gateway.\nData Points and Sync Status\nSync Status for AirLink routers and Gateways are also affected by specific data values that are expected to be sent to ALMS. The Sync Status is updated any time a router successfully receives valid data for one of the data points listed below. The set of relevant data points varies for AirLink OS-based routers and ALEOS-based routers.\nALEOS Data Points\nlwm2m.3.0.1 (model number)\nlwm2m.3.0.2 (serial number)\nlwm2m.3.0.3 (firmware version)\nlwm2m.10241.0.1 (iccid)\nlwm2m.10241.0.0 (imei)\nlwm2m.10421.0.2 (imsi)\nlwm2m.4.0.4.0 (ip address)\nlwm2m.10241.0.3 (phone number)\nlwm2m.1.0.1 (lifetime)\nAirLink OS Data Points\ndevice.provisioning.hardware\ndevice.provisioning.mac.eth\ndevice.machine\ndevice.provisioning.serial\nnet.interface.cellular[c1].iccid\nnet.interface.cellular[c1].imei\nnet.interface.cellular[c1].ipv4.address\nnet.interface.cellular[c1].ipv6.address\nnet.interface.cellular[c1].voicenumber\nnet.interface.cellular[c1].operator\nnet.interface.cellular[c1].homeoperator\nservices.lwm2m.state.revision\nservices.lwm2m.client.heartbeat\nSynchronization Logs\nTo view Synchronization Logs:\nGo to Monitor > Systems.\nSelect the desired system.\nIn the System Communication widget, click the Sync Status indicator.\nThe Synchronization Logs screen appears.\nThe four buttons filter the log messages by severity.\nThe Log message levels are:\nAll logs\n\u2014Click to display messages from all levels. This is the default.\nInfo\n\u2014Click to display only the lowest level informational messages. These messages provide useful information, and your systems are not negatively impacted when in this state.\nWarning\n\u2014Click to display Warning messages. Warnings are important to understand but may or may not impact the function of the AirLink router. In many cases these messages relate to the state of the cellular subscription that comprises the System and not the router itself.\nError\n\u2014Click to display Error messages. Error (red) message are the highest level, and should be reviewed. But even in an Error state, the functionality of the router may not be affected.\nThe Systems Sync Status will always reflect the highest level log message received by ALMS. For example, one entry in the \u201Chigher\u201D warning state will change the router\u2019s Sync Status to \u201CWarning\u201D (yellow); if an \u201CError\u201D message is logged, it will change it to red.\nCommon Error Messages\nThe following messages may appear in Synchronization Logs.\nMESSAGE\nRECOMMENDED ACTION\n(Info) IP address updated [10.206.166.207]\nThis Info message is provided if the IP address of the System changes from one check in to the next. This will occur if your SIMs are dynamically addressed and have been updated by your carrier. This is unlikely to affect the performance of your System.\n(Info) Firmware updated [ALEOS RV55 LWM2M (4.15.4.002)]\nThis message notifies you that the firmware on your router has been updated to a specific version.\n(Error) Subscription already registered in a different domain [identifier=89011703278562854797,networkidentifier 310170856285479\nSubscription is managed by a different company. Expected when intentionally managing gateways and subscriptions in different companies. Otherwise, contact Sierra Wireless to determine where the subscription is registered.\n(Error) [subscription.not.linked.to.system]\nAppears for 3rd party SIMs. Can be safely ignored.\n(Error) Subscription already used by another system [identifier=89302720395910599817,networkIdentiier..\nThe AirLink router is reporting in with a SIM that is already reported in another System. This normally occurs when a SIM card has been moved from one router to another, typically when the router is decommissioned, but not deleted from ALMS. If the system is no longer needed, please delete it from ALMS then force a Sync of the current System.\nA subscription already exists with this identifier [mobileNumber=NA]\nSystem detects that there is a duplicate phone number associated with another subscription (often seen when a data-only SIM sends a null value for mobileNumber). Ignore.\nData Currency in ALMS\nIn addition to the Sync Status, there are other visual clues in ALMS about the currency of the data in the ALMS user interface. The System Info widget displays the various data points in different colors, to indicate how the data has been reported to ALMS, relative to the Heartbeat interval that has been set in the Configure Communication settings.\nFor more information on the System Info widget and how data points are diplayed, see the\nSystem Information\nsection on\nthis page\n.\nCommunication Status\nThe final element that will provide you with insight into the state of your device is Communication Status. This identifies if the device has communicated with ALMS relative to the time frame expected, as defined in\nConfigure Communications\n."})]})}function m(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>a});var o=n(6540);let r={},i=o.createContext(r);function s(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);